var t=`1362-lechona`;var o=`world-1362`;var n=`CO`;var r=`south-america`;var a=8;var s=282;var h={en:`Lechona`,ua:`Лечона`};var g={en:`Lechona is a dish from Colombia featuring pork shoulder, garlic, orange juice, white rice. This home-sized recipe records each ingredient at the step where it is used. Small home lechona-style pork roast with rice stuffing, not a whole deboned stuffed pig.`,ua:`Лечона, страва кухні країни Колумбія з такими основними складниками: свиняча лопатка, часник, апельсиновий сік, білий рис. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Домашній невеликий рулет зі свинини з рисовою начинкою за мотивами лечони, а не ціле фаршироване порося.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`pork-shoulder`,1200,`g`],[`garlic`,7,`clove`],[`ground-cumin`,6,`g`],[`orange-juice`,110,`ml`]]},{en:`Cook the measured rice with stock and peas until tender, cool promptly, and use this cooked mixture as the stuffing for the pork roast.`,ua:`Зваріть рис із бульйоном та горошком до м’якості, швидко охолодіть і використайте готову суміш для фарширування свинячого рулету.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`white-rice`,400,`g`],[`chicken-stock`,650,`ml`],[`frozen-green-peas`,140,`g`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:14,i:[]},{en:`Roast the already seasoned food in a preheated oven until tender and safely cooked, using a thermometer for meat or poultry.`,ua:`Запікайте вже приправлені продукти в розігрітій духовці до м’якості та готовності, перевіряючи температуру м’яса термометром.`,t:[`roasting`],m:150,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,30,`g`]]}];var u={slug:t,id:o,country:`CO`,region:r,servings:8,minutes:282,title:h,text:g,steps:l};export{n as country,u as default,o as id,s as minutes,r as region,a as servings,t as slug,l as steps,g as text,h as title};